import { Suspense } from 'react'

function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card skeleton">
        <h2>Total Revenue</h2>
        <p className="skeleton-text">$0</p>
      </div>
      <div className="card skeleton">
        <h2>Total Invoices</h2>
        <p className="skeleton-text">0</p>
      </div>
    </div>
  )
}

async function CardStatsData() {
  const res = await fetch('https://api.example.com/dashboard/stats')
  const data = await res.json()

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${data.totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{data.totalInvoices}</p>
      </div>
    </div>
  )
}

export function CardStats() {
  return (
    <Suspense fallback={<CardStatsSkeleton />}>
      <CardStatsData />
    </Suspense>
  )
}

